import {initialState,transition,restoreState,canConfirm,STORAGE_KEY} from './model.js';

const root=document.querySelector('#main');
const announcement=document.querySelector('#announcement');
let state=initialState();
try {state=restoreState(sessionStorage.getItem(STORAGE_KEY));} catch {}
let view=['current','reasoning'].includes(location.hash.slice(1))?location.hash.slice(1):'prototype';
let inboxCategory='input', listStatus='progress', searchQuery='', searchOpen=false;
let screen='inbox', reviewOpen=false, reviewTab='understanding', kind='scope', draft='', error='';
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const phaseLabels={request:'Waiting for your input',rechecking:'Re-evaluating understanding',revised:'Revised plan · needs review',agreed:'Understanding confirmed',working:'Working on approved plan',delivered:'Demo result ready'};
const exampleCorrections={
  scope:'The issue is about desktop signup spacing. Keep every field, sign-up option, and validation rule. Please revise your plan without changing signup behaviour.',
  evidence:'What evidence shows that validation causes the layout problem? Compare your recommendation with the report before proposing a fix.',
  constraint:'Keep this change limited to the desktop signup layout. Do not change the login screen, authentication logic, or mobile experience.'
};
const latest=()=>state.corrections.at(-1);
const button=(text,action,primary=false,extra='')=>`<button class="button${primary?' primary':''}" data-action="${action}" ${extra}>${text}</button>`;
function approvalButton(){return ['request','revised','agreed'].includes(state.phase)?button('✓ Approve plan v'+state.version,'approve',true):'';}
function approvalChoice(){return ['request','revised'].includes(state.phase)?`<div class="approval-choice"><h3>Already understand and agree?</h3><p>You can approve the plan as shown, or question it below. Structured confirmation is optional.</p>${approvalButton()}<small>This demo authorizes a plan version, not a live Ziki pipeline gate. Approval does not verify the plan’s assumptions or results.</small></div>`:'';}
function save(){try{sessionStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{}}
function notify(text){announcement.textContent=text;}
function dispatch(action){const next=transition(state,action);if(next===state)return;state=next;save();render();}
function agentAvatar(){return '<img class="agent-avatar" src="logo.svg" alt="">';}
function tag(text,type=''){return `<span class="tag ${type}">${text}</span>`;}
function icon(name, className=''){
  const paths={inbox:'<path d="M4 4h16l3 10v6H1v-6zM1 14h6l2 3h6l2-3h6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',filter:'<path d="M3 3h18l-7 8v9l-4-3v-6z"/>',sort:'<path d="M7 3v18m-4-4 4 4 4-4M17 21V3m-4 4 4-4 4 4"/>',plus:'<path d="M12 4v16M4 12h16"/>',monitor:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M12 17v4m-5 0h10"/>',open:'<circle cx="12" cy="12" r="8" stroke-dasharray="3 3"/>',progress:'<circle cx="12" cy="13" r="8"/><path d="M9 1h6m-3 12 4-4"/>',done:'<circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/>',bot:'<path d="M12 2v3M4 8h16v12H4zM1 11v6m22-6v6M8 13h.01M16 13h.01M9 17h6"/>',gear:'<path d="m9 3 1-2h4l1 2 3 2 2 1v4l-2 1-1 3 1 2-3 3-2-1-3-1-2 1-3-3 1-2-1-3-2-1V6l2-1z"/><circle cx="12" cy="10" r="3"/>'};
  return `<svg class="ui-icon ${className}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.inbox}</svg>`;
}
function toolbar(){return `<div class="app-toolbar"><div class="breadcrumbs"><span class="muted">Zedu</span><span class="chevron">›</span>${view==='prototype'?'<h1 class="app-page-title">Issues</h1>':'<strong>Issues</strong>'}${screen==='issue'?'<span class="chevron">›</span><span class="muted">#106</span>':''}</div><div class="reference-tools"><button class="tool-button" data-action="search" aria-label="Search sample issues" aria-expanded="${searchOpen}">${icon('search')}</button><button class="tool-button" data-action="filter" aria-label="Show sample filter">${icon('filter')}</button><button class="tool-button" data-action="sort" aria-label="Show sample sort">${icon('sort')}</button><button class="tool-button" data-action="new-issue" aria-label="About creating issues in this prototype">${icon('plus')}</button><button class="platform-tool" data-action="platform">${icon('monitor')}<strong>Platform: All</strong><span class="count">${state.phase==='working'?0:1}</span><span class="muted">⌄</span></button></div></div>${searchOpen?`<form class="sample-search" id="search-form"><label for="sample-search">Search the sample issue</label><input id="sample-search" type="search" value="${escape(searchQuery)}" placeholder="Search by title or #106"><button class="button" type="submit">Search</button></form>`:''}<div class="toolbar-feedback" id="toolbar-feedback" role="status" hidden></div>`;}
function tabs(){return `<nav class="status-tabs" aria-label="Issue views"><button data-action="inbox" class="inbox-button ${screen==='inbox'?'active':''}">${icon('inbox')} Inbox <span class="count">${state.phase==='working'?0:1}</span></button><div class="issue-status-group">${[['open','Open','open',0],['progress','In progress','progress',1],['done','Done','done',0],['all','All','inbox',1]].map(([key,label,symbol,count])=>`<button data-action="queue" data-status="${key}" class="${((screen==='queue'&&listStatus===key)||(screen==='issue'&&key==='progress'))?'active':''}"><span class="status-symbol ${key}">${icon(symbol)}</span><span>${label}</span><span class="status-total">${count}</span></button>`).join('')}</div></nav>`;}
function inbox(){
  const finished=state.phase==='delivered', active=state.phase==='working';
  const hasIssue=inboxCategory==='input' && (!searchQuery || ('desktop sign up screen signup default window #106').includes(searchQuery.toLowerCase()));
  return `<section class="inbox-guide" aria-labelledby="inbox-guide-title"><div class="inbox-guide-copy"><span class="guide-icon">${icon('inbox')}</span><div><h2 id="inbox-guide-title">How the Inbox works</h2><p>Agents work through issues on their own and stop here when they need a person: to answer a question, give feedback on a design, or weigh in on a new idea.</p></div></div><aside class="reference-agent"><h3>YOUR AGENTS</h3><div class="reference-agent-row"><span class="robot-avatar">${icon('bot')}</span><div class="reference-agent-details"><strong>Netrunner</strong><span class="agent-state">${active?'Working':finished?'Review ready':'Needs your input'}</span><p>${active?'Following approved plan':finished?'Sample result ready':'Waiting on issue #106'}</p><small>Sample agent · no live connection</small></div><span class="agent-work">Work</span><span class="agent-gear">${icon('gear')}</span></div><div class="agent-carousel" aria-label="One sample agent"><span class="current"></span><span></span><span></span><span></span><span></span></div></aside></section>
    <nav class="inbox-categories" aria-label="Inbox lists">${[['input','Need your input',1],['design','Design feedback needed',0],['ideas','New ideas',0]].map(([key,label,count])=>`<button class="${inboxCategory===key?'active':''}" data-category="${key}" aria-pressed="${inboxCategory===key}">${label}<span class="count">${count}</span></button>`).join('')}</nav>
    ${hasIssue?`<article class="notification-card reference-request"><div class="card-top"><div class="waiting-label"><span class="status-dot"></span> ${escape(phaseLabels[state.phase]).toUpperCase()}</div><h3>${finished?'The signup layout is ready for review':active?'Desktop signup layout · work in progress':'Desktop Sign up screen doesn’t fit in the default window'}</h3><p class="issue-ref">#106 · Design · Desktop · sample issue</p><div class="agent-message"><span class="agent-name">NETRUNNER</span><p>${state.phase==='request'?'“I can make the form fit by removing the optional fields and simplifying validation. Shall I proceed?”':state.phase==='rechecking'?'“I need to re-check the report and your correction before proposing another approach.”':finished?'“The simulated layout change is ready. Please review what changed and what remains unverified.”':active?(state.version===1?'“I’m applying the approved plan: remove optional fields and simplify validation.”':'“I’m following the layout-only plan you approved.”'):'“The revised plan preserves all fields, sign-up options, and validation. Does this match your intent?”'}</p></div><div class="card-actions">${approvalButton()}${button(finished?'Review demo result':active?'Review progress':'Review understanding','review',false)}<button class="text-button" data-action="issue">Open issue</button></div></div><div class="card-foot">${active?'Approval applies to plan v'+state.version:finished?'Illustrative completion · no real fix was executed':'Approve if you understand the plan, or review and correct it before continuing.'}</div></article>`:`<section class="reference-empty"><h3>Nothing here right now.</h3><p>${searchQuery?'No sample issue matches your search.':'No agent is waiting on '+(inboxCategory==='design'?'design feedback.':inboxCategory==='ideas'?'a new idea.':'an answer.')}</p><button class="text-button" data-action="clear-filters">Clear filters</button></section>`}`;
}
function issueQueue(){
  const show=['progress','all'].includes(listStatus)&&(!searchQuery||('desktop signup sign up default window #106').includes(searchQuery.toLowerCase()));
  return `<section class="sample-issue-table"><div class="sample-table-head"><span>Votes</span><span>Issue</span><span>Status</span><span>Priority</span></div>${show?`<button class="sample-issue-row" data-action="issue"><span class="sample-votes">⌃<br>6</span><span><strong>Desktop Sign up screen doesn’t fit in the default window</strong><small>#106 · Design · Desktop · sample issue</small></span><span class="green">${state.phase==='working'?'In progress':'Needs your input'}</span><span class="muted">Medium</span></button>`:'<div class="reference-empty"><h3>No sample issues in this view.</h3><p>This focused prototype contains one interactive issue.</p></div>'}</section>`;
}
function issue(){return `<button class="text-button back" data-action="inbox">← Back to Inbox</button><div class="issue-layout ${reviewOpen?'with-review':''}"><article class="issue-main"><h2 class="issue-title"><span>#106</span> Desktop Sign up screen doesn’t fit in the default window</h2><div class="tags">${tag('Design')}${tag('Desktop')}${tag('Sample scenario')}</div>
  <section class="content-section"><h3>DESCRIPTION</h3><div class="description-copy"><p>At the desktop app’s default <strong>1280 × 720</strong> window size, the signup form is too tall. Social sign-up options and terms text fall below the visible area.</p><p><strong>Goal:</strong> fit the complete form in the default window by adjusting layout and spacing.</p></div><div class="scope-note">Keep all fields, text, sign-up options, validation, and signup behaviour. The login screen and signup logic are out of scope.</div></section>
  <section class="content-section"><h3>AGENT DECISIONS</h3><div class="decision-summary">${agentAvatar()}<div><strong>Netrunner · ${state.version===1?'proposed approach':'plan v'+state.version}</strong><p>${state.version===1?'Reduce form height by removing optional fields and simplifying validation.':'Layout and spacing only. Keep authentication and signup behaviour unchanged.'}</p>${!reviewOpen?approvalButton()+button('Review understanding ↗','review',false):'<span class="small blue">Review is open alongside the issue →</span>'}</div></div></section>
  <section class="content-section"><h3>CONVERSATION</h3><div class="thread-item"><div class="thread-header"><span class="avatar">T</span><strong>Demo teammate</strong><small>Reporter</small></div><p>The signup screen should fit without removing any signup options. Please keep the change limited to layout.</p></div>
  ${state.corrections.map((item,index)=>`<div class="thread-item"><div class="thread-header"><span class="avatar">Y</span><strong>You</strong><small>Correction ${index+1}</small></div><p>${escape(item.text)}</p></div>`).join('')}
  ${state.version>1?`<div class="thread-item"><div class="thread-header">${agentAvatar()}<strong>Netrunner</strong><small>Revised understanding · v${state.version}</small></div><p>The original recommendation changed behaviour outside the requested scope. The revised plan adjusts spacing and social-button layout, preserving all fields and validation.</p></div>`:''}
  ${state.approvedVersion?`<div class="thread-item"><div class="thread-header"><span class="avatar">✓</span><strong>Plan v${state.approvedVersion} approved</strong></div><p>${state.version===1?'The original proposal was approved directly, without structured confirmation. This permits its proposed behaviour changes.':'Approval applies to the current layout plan.'} Further material changes require new approval.</p></div>`:''}
  </section></article>${reviewOpen?review():`<aside class="issue-side"><div><p class="section-kicker">STATUS</p>${tag(['working','delivered'].includes(state.phase)?'In progress':'Waiting for input','amber')}</div><div><p class="section-kicker">PEOPLE</p><div class="agent-row">${agentAvatar()}<div><strong>Netrunner</strong><p>Sample contributor</p></div></div></div><div><p class="section-kicker">YOUR CONTROL</p><p>Review the agent’s understanding at any point—not only when it asks a question.</p><br>${button('Review understanding','review',true)}</div></aside>`}</div>`;}
function review(){
  const phaseIndex={request:0,rechecking:1,revised:2,agreed:3,working:3,delivered:4}[state.phase];
  return `<section class="review-panel" aria-labelledby="review-title"><header class="review-header"><div><p class="section-kicker">HUMAN + AGENT REVIEW</p><h2 id="review-title" tabindex="-1">Review understanding</h2><p>#106 · Netrunner · Plan v${state.version}</p></div><button class="icon-button" data-action="close-review" aria-label="Close review panel">×</button></header>
    <div class="review-tabs" role="tablist" aria-label="Review information"><button role="tab" aria-selected="${reviewTab==='understanding'}" class="${reviewTab==='understanding'?'active':''}" id="tab-understanding" aria-controls="review-body" tabindex="${reviewTab==='understanding'?0:-1}" data-tab="understanding">Understanding</button><button role="tab" aria-selected="${reviewTab==='evidence'}" class="${reviewTab==='evidence'?'active':''}" id="tab-evidence" aria-controls="review-body" tabindex="${reviewTab==='evidence'?0:-1}" data-tab="evidence">Evidence</button><button role="tab" aria-selected="${reviewTab==='history'}" class="${reviewTab==='history'?'active':''}" id="tab-history" aria-controls="review-body" tabindex="${reviewTab==='history'?0:-1}" data-tab="history">Changes <span class="count">${state.version-1}</span></button></div>
    <div class="review-content"><div class="phase-track" aria-hidden="true">${Array.from({length:5},(_,i)=>`<span class="${i<=phaseIndex?'done':''}"></span>`).join('')}</div>
    <div class="paused-banner ${['agreed','working','delivered'].includes(state.phase)?'success':''}"><span>${['working','delivered'].includes(state.phase)?'✓':'Ⅱ'}</span> ${escape(phaseLabels[state.phase])}${state.phase==='agreed'?' · not yet authorized':''}</div>
    <div role="tabpanel" id="review-body" aria-labelledby="tab-${reviewTab}">${reviewTab==='evidence'?evidence():reviewTab==='history'?reviewHistory():understanding()}</div>
    ${!['rechecking','delivered'].includes(state.phase)?composer():''}
    </div><div class="review-footer"><span>◉</span> Scripted demonstration. Nothing is sent to Ziki.</div></section>`;
}
function understanding(){
  if(state.phase==='rechecking')return `<div class="review-label">YOUR CORRECTION</div>${latest()?`<div class="user-correction"><p>${escape(latest().text)}</p></div>`:''}<div class="understanding-block"><div class="review-label">AGENT ACKNOWLEDGEMENT · SIMULATED</div><p>I need to test my interpretation against the original report and your correction. The proposed action stays paused. I won’t treat this message as approval.</p></div><div class="recheck-card"><h3>What gets re-checked?</h3><p>The requested outcome, the proposed cause, changes outside the agreed scope, and evidence still missing.</p>${button('Run simulated re-check →','recheck',true)}<div class="simulation-note">This sample re-check is pre-written for the signup scenario. It does not run an AI agent or inspect a repository.</div></div>`;
  if(state.phase==='delivered')return result();
  if(state.phase==='working')return `<div class="understanding-block"><div class="review-label">APPROVED PLAN V${state.version} · ${state.approvalMode==='direct'?'DIRECT APPROVAL':'AFTER SHARED CONFIRMATION'}</div><p>${state.version===1?'Remove optional fields and simplify validation to make the form shorter.':'Adjust desktop signup spacing and the social-button row. Preserve all fields, validation, authentication, and the login screen.'}</p></div><div class="execution-summary"><h3>What your approval permits</h3><p>${state.version===1?'The agent follows the original proposal, including its changes to fields and validation. The layout-only scope has not been reconciled with this plan.':'The agent follows this specific layout-only plan. A broader change needs new approval.'}</p><p class="small muted">${state.approvalMode==='direct'?'You chose direct approval. No structured confirmation was recorded.':'You confirmed the direction before approving.'}</p></div><p class="simulation-note">No real code is being changed. Continue to see the scripted outcome, or pause and correct the direction.</p><div class="outcome-actions">${button('Show simulated outcome →','complete',true)}${button('Pause and correct','pause')}</div>`;
  let content=`<div class="understanding-block"><div class="review-label">WHAT I THINK THE TASK IS</div><p>Make the complete desktop signup form fit in the default 1280 × 720 window.</p></div>`;
  if(state.phase==='request')return content+`<div class="understanding-block"><div class="review-label">WHAT I OBSERVED</div><p>The report says social sign-up buttons and terms text are cut off. It identifies large fixed gaps in the layout.</p></div><div class="understanding-block"><div class="review-label">MY ASSUMPTION</div><div class="assumption">${tag('Not verified')}<br>There are too many fields and too much validation for this window size.</div></div><div class="understanding-block"><div class="review-label">MY PROPOSED APPROACH</div><ol class="plan-list"><li><b>01</b> Remove optional fields</li><li><b>02</b> Simplify validation</li><li><b>03</b> Recheck whether the form fits</li></ol></div><p class="evidence-warning">Notice the gap: the report requests a layout change; this plan changes signup behaviour.</p>`+approvalChoice();
  content+=`<div class="understanding-block"><div class="review-label">WHAT CHANGED IN MY UNDERSTANDING</div><p>The form’s layout is the reported problem. Removing fields or changing validation does not respect the requested scope. The earlier cause was an assumption, not a verified finding.</p></div><div class="version-diff"><div class="removed"><small>REMOVED FROM PLAN V${state.version-1}</small>${state.version===2?'Remove fields and simplify validation.':'Previous layout plan returned for another review.'}</div><div class="added"><small>REVISED PLAN V${state.version}</small>Adjust spacing and the social-button row. Preserve signup behaviour.</div></div><ul class="plan-list"><li><b>01</b> Reduce excessive vertical gaps</li><li><b>02</b> Place social sign-up buttons in a compact row</li><li><b>03</b> Check fit at 1280 × 720 and test smaller/resized windows</li></ul><div class="scope-note">Keep all fields, options, text, validation, and authentication. No login or mobile changes.</div>`;
  if(latest())content+=`<div class="understanding-block" style="margin-top:18px"><div class="review-label">YOUR LATEST DIRECTION</div><div class="user-correction"><p>${escape(latest().text)}</p></div><p class="simulation-note">Free-text corrections are recorded verbatim. This scripted prototype cannot determine whether every custom constraint is satisfied; check the plan and continue the discussion if it does not match.</p></div>`;
  if(state.phase==='agreed')return content+`<div class="recheck-card"><h3>We agree on the direction.</h3><p>Understanding is confirmed. Work is still paused until you authorize this exact plan.</p>${button('Approve revised plan v'+state.version+' →','approve',true)}<p class="simulation-note">Permits only the layout changes above. It does not approve deployment, authentication changes, or a broader redesign.</p></div>`;
  return content+approvalChoice()+`<div class="composer"><h3>Prefer a structured confirmation?</h3><p>Use these checks to explicitly confirm shared understanding before approving. You can also approve directly above, or continue correcting below.</p><label class="agreement-check"><input type="checkbox" data-check="goal" ${state.confirmed.includes('goal')?'checked':''}> The goal matches the issue.</label><label class="agreement-check"><input type="checkbox" data-check="scope" ${state.confirmed.includes('scope')?'checked':''}> The scope and constraints match my direction.</label><label class="agreement-check"><input type="checkbox" data-check="evidence" ${state.confirmed.includes('evidence')?'checked':''}> I understand the evidence and remaining checks.</label>${button('Confirm shared understanding →','agree',true,canConfirm(state)?'':'disabled')}<p class="simulation-note">Confirmation records understanding. Approval is a separate next step.</p></div>`;
}
function evidence(){return `<div class="review-label">EVIDENCE, NOT HIDDEN REASONING</div><p class="small muted">Reported facts, assumptions, and checks are shown separately. This is not a transcript of an agent’s private reasoning.</p><article class="evidence-card"><h3>01 · The issue report</h3><p>The desktop signup form exceeds the default window. Large fixed gaps are identified as the layout problem.</p><blockquote>Keep the fields, sign-up behaviour, and validation unchanged.</blockquote><small>Paraphrased from the public report · inspected 27 Oct 2026</small><a href="https://ziki.dev/issues/106" target="_blank" rel="noreferrer">Open original issue #106 ↗</a></article><article class="evidence-card"><h3>02 · The mismatch</h3><p>The sample agent recommends removing fields and changing validation. That changes behaviour outside a layout-only request.</p><small>Illustrative agent proposal written for this prototype</small></article><article class="evidence-card"><h3>03 · What is still unverified?</h3><p>No source repository has been inspected here. No layout, authentication, or device tests have actually run. A real agent would need linked screenshots, diffs, and test results.</p><small>Explicit limits of this demonstration</small></article>`;}
function reviewHistory(){return `<div class="review-label">A RECORD YOU CAN FOLLOW</div><div class="evidence-card"><h3>v1 · Original proposal</h3><p>Remove optional fields and simplify validation. No approval granted.</p></div>${state.corrections.map((item,i)=>`<div class="evidence-card"><h3>Correction ${i+1} · You</h3><p>${escape(item.text)}</p></div>`).join('')}${state.version>1?`<div class="evidence-card"><h3>v${state.version} · Revised proposal</h3><p>Layout and spacing only. Keep fields and signup behaviour. ${state.approvedVersion===state.version?'Approved for this version · '+(state.approvalMode==='direct'?'direct approval; no structured confirmation.':'after shared confirmation.'):'No current approval.'}</p></div>`:''}<p class="simulation-note">Every new correction invalidates prior confirmation and approval. A revised plan needs a fresh review.</p>`;}
function result(){
  const wrong=state.version===1;
  return `<div class="completion ${wrong?'scope-failure':''}"><span>${wrong?'! SAMPLE CONSEQUENCE':'✓ SAMPLE COMPLETION REPORT'}</span><h3>${wrong?'The form fits. But it solves the wrong problem.':'The sample result stays within the requested scope.'}</h3><p>${wrong?'The approved proposal was followed, but it removed a field and changed validation. A shorter form is not the same as fitting the existing form.':'Spacing and button layout changed; fields and signup behaviour stayed the same.'}</p></div><div class="outcome-comparison"><div><span class="review-label">WHAT THE ISSUE ASKED FOR</span><strong>Fit the existing signup form</strong><p>Keep all fields, options, and validation. Change layout only.</p></div><div class="${wrong?'comparison-risk':'comparison-good'}"><span class="review-label">SIMULATED PLAN V${state.version} OUTCOME</span><strong>${wrong?'Field removed · validation simplified':'Full form retained · spacing reduced'}</strong><p>${wrong?'Information collected by that field is lost. Changed validation needs separate assessment. The original scope is not satisfied, so correction and re-testing are needed.':'The illustrated change matches the task’s scope. Actual implementation and testing still need real evidence.'}</p></div></div><div class="approval-receipt"><strong>Approval record</strong><p>Plan v${state.version} · ${state.approvalMode==='direct'?'approved directly, without structured confirmation':'approved after shared confirmation'}.</p><p>${wrong?'Approval gave permission to act; it did not establish that the plan was appropriate.':'Direct approval can be appropriate when the human already understands and agrees with the plan. The choice of approval route alone does not determine whether a plan is right.'}</p></div><div class="evidence-card"><h3>${wrong?'Why this outcome matters':'Verification report'} · illustrative</h3><p>${wrong?'Visual fit: sample pass.<br>Preserve all fields: sample fail.<br>Preserve validation: sample fail.<br>Recovery: pause, correct scope, and review a revised plan.':'Default-window layout: sample pass.<br>Resized-window behaviour: still needs verification.<br>Authentication regression: still needs verification.'}</p><small>All outcomes are scripted. No fields were actually removed, validation changed, or tests against Zedu run.</small></div><div class="outcome-actions">${button(wrong?'Reopen and correct →':'Question this result','reopen',wrong)}${button('Replay this scenario ↺','reset')}</div><p class="simulation-note">${wrong?'To compare outcomes, revise the plan to layout-only and approve v2 directly. It follows the same shortcut without the illustrated scope error.':'A real completion must link the change and actual verification evidence.'}</p>`;
}
function composer(){return `<form class="composer" id="correction-form"><h3>${state.phase==='working'?'Need to redirect the work?':'Question or correct the direction'}</h3><p>${state.phase==='working'?'A correction pauses the simulated work and invalidates its prior approval.':'The agent should explain or revise its interpretation—not just ask you to approve it.'}</p><div class="chips"><button type="button" class="chip ${kind==='scope'?'active':''}" data-kind="scope">That’s outside scope</button><button type="button" class="chip ${kind==='evidence'?'active':''}" data-kind="evidence">Show the evidence</button><button type="button" class="chip ${kind==='constraint'?'active':''}" data-kind="constraint">Add a constraint</button></div><label class="sr-only" for="correction">Your question or correction</label><textarea id="correction" name="correction" maxlength="1000" placeholder="Tell the agent what seems wrong or what it needs to reconsider…" aria-describedby="correction-help">${escape(draft)}</textarea><p id="correction-help" class="simulation-note">Use a suggested correction or write your own. Do not enter sensitive information.</p>${error?`<p class="form-error" role="alert">${error}</p>`:''}<div class="composer-bottom"><small>Recorded locally in this tab</small><button class="button primary" type="submit">Send for re-evaluation ↑</button></div></form>`;}
function currentPattern(){return `<article class="reasoning"><header class="reasoning-head"><p class="eyebrow">EXISTING ZIKI · VERIFIED 28 OCT 2026</p><h2>The conversation already exists.<br>Make the agreement easier to follow.</h2><p>Ziki already lets people instruct agents, answer questions, and review approvals. This proposal improves how a person inspects and corrects a plan within an issue.</p></header><div class="reasoning-grid"><section class="reason-block"><span class="reason-number">01 / INSTRUCTIONS & MESSAGES</span><h3>People can already guide agents.</h3><p>Agents → Manage agents → Messages and instructions provides a standing brief and a conversation. Owners can send direction and see agent questions.</p><p><a href="https://ziki.dev/settings/agents" target="_blank" rel="noreferrer">Open agent settings ↗</a></p></section><section class="reason-block"><span class="reason-number">02 / QUESTIONS & APPROVALS</span><h3>Requests already reach a human.</h3><p>The Inbox collects requests for input. Activity & Approvals distinguishes guidance replies from workspace pipeline approvals. An escalation response is not permission to pass a merge gate.</p><p><a href="https://ziki.dev/activity" target="_blank" rel="noreferrer">Open Activity & Approvals ↗</a></p></section><section class="reason-block"><span class="reason-number">03 / ISSUE CONTEXT</span><h3>Evidence and conversation are available.</h3><p>Issue pages contain the report, agent decisions, replies, bids, and activity. A human can use these to investigate an approach and ask questions.</p><p><a href="https://ziki.dev/issues/106" target="_blank" rel="noreferrer">Open inspected issue #106 ↗</a></p></section><section class="reason-block"><span class="reason-number">04 / THE PROPOSED CHANGE</span><h3>Make the issue-specific agreement explicit.</h3><p>Our review panel brings the goal, evidence, assumptions, correction, changed plan, and approval version together beside the issue. Direct approval remains available. A correction clears the prototype’s old authorization.</p></section><section class="reason-block wide"><span class="reason-number">WHAT THIS COMPARISON ESTABLISHES</span><h3>An interaction improvement to an existing workflow.</h3><p>These existing mechanisms were verified in the live interface and <a href="https://ziki.dev/llms.txt" target="_blank" rel="noreferrer">API reference</a>. We did not find this exact structured plan-review lifecycle in the screens inspected; that is not proof that no similar capability exists anywhere in Ziki. The proposed reduction in confusion still needs user testing.</p><p>The sample demonstrates plan approval only. Production integration must preserve Ziki’s owner/admin permissions and separate pipeline gates. No real execution or authorization is performed here.</p></section></div><div style="margin-top:24px">${button('Try the proposed review →','try',true)}</div></article>`;}
function reasoning(){return `<article class="reasoning"><header class="reasoning-head"><p class="eyebrow">THE DESIGN REASONING</p><h2>A decision is only useful<br>if we understand the work behind it.</h2><p>A human needs a way to question an agent’s interpretation, check its direction, and correct mistakes before authorizing the next step.</p></header><div class="reasoning-grid"><section class="reason-block"><span class="reason-number">01 / THE PROBLEM</span><h3>“Approve?” can hide a misunderstanding.</h3><p>An agent can ask a clear question about the wrong action. Ziki already supports clarification through questions, messages, and comments. This proposal makes the issue-specific goal, assumptions, revised plan, and approval scope explicit in one review panel.</p></section><section class="reason-block"><span class="reason-number">02 / THE EXISTING HOME</span><h3>Extend the issue, not the dashboard.</h3><p>Ziki’s Inbox already collects requests for human input. Messages and instructions already support human direction, and Activity & Approvals separates guidance from pipeline permission. Issue details already show agent decisions and conversation. Add a review entry at the request and a review panel beside the issue. The same entry can be available during ongoing agent work. A direct approval option remains available when the person already understands and agrees with the plan.</p></section><section class="reason-block wide"><span class="reason-number">03 / THE INTERACTION</span><h3>Make understanding something both sides can check.</h3><p>The agent separates observations from assumptions. A human can inspect evidence and supply a correction. The agent re-evaluates, shows the revised plan, and asks the human to confirm the direction. Approval then applies to that specific version. The person can also approve a shown plan directly; structured confirmation is an optional route, not a mandatory ceremony.</p><div class="rationale-flow"><span>Agent proposal</span><i>→</i><span>Human challenge</span><i>→</i><span>Re-evaluation</span><i>→</i><span>Revised agreement</span><i>→</i><span>Scoped approval</span></div></section><section class="reason-block"><span class="reason-number">04 / WHY THESE DETAILS</span><h3>Corrections must change the workflow.</h3><ul><li>Work stays paused during review.</li><li>Changes are visible, not silently overwritten.</li><li>Understanding and authorization are separate; direct approval remains available.</li><li>A new correction clears old approval.</li><li>Completion returns with evidence and a way to reopen.</li></ul></section><section class="reason-block"><span class="reason-number">05 / WHAT WE WOULD MEASURE</span><h3>Does it help people steer the work?</h3><p>In a user test, ask someone to spot the scope mismatch, correct it, identify the revised plan, and explain what they approved. Measure completion, misunderstandings, and the time taken. No usability results are claimed here.</p></section><section class="reason-block wide"><span class="reason-number">06 / HONEST SCOPE & ATTRIBUTION</span><h3>A working interaction prototype. A simulated agent.</h3><p>The Inbox and issue styling are inspired by <a href="https://ziki.dev" target="_blank" rel="noreferrer">Ziki</a>. The layout-only scenario is adapted from <a href="https://ziki.dev/issues/106" target="_blank" rel="noreferrer">issue #106</a>; the mistaken proposal, agent responses, and completion report are fictional. The header recreates the user-supplied reference snapshot; the issue actors and agent exchange are sample data.</p><p>We reviewed <a href="https://ziki-desk.vercel.app/" target="_blank" rel="noreferrer">Michael Churchill’s Ziki Desk</a> as a related prototype. Its decision-focused dashboard helped identify overlap with our earlier idea. This submission focuses on questioning, repairing, and agreeing on an agent’s understanding inside an issue. It does not incorporate Ziki Desk’s code or dashboard.</p><p>The prototype uses browser-tab storage and a scripted state machine. It has no live Ziki API, AI integration, actual code execution, notifications, or permissions enforcement. A production version needs authenticated issue/agent access, linked evidence, plan-version storage, and execution gates on the server. Its plan approval must preserve Ziki’s separate workspace-admin pipeline gates; an owner’s correction or reply must not grant merge permission.</p><p>Design principles apply to an agent waiting for a person or an agent being redirected. Offline or idle status alone is not proof that an agent is stuck or mistaken.</p></section></div><div style="margin-top:24px">${button('Try the full exchange →','try',true)}</div></article>`;}
function render(){
  document.body.classList.toggle('prototype-view',view==='prototype');
  document.querySelectorAll('[data-view]').forEach(item=>{const active=item.dataset.view===view;item.classList.toggle('selected',active);item.setAttribute('aria-pressed',String(active));});
  root.innerHTML=view==='reasoning'?reasoning():view==='current'?currentPattern():`<div class="app-shell">${toolbar()}<div class="app-body">${tabs()}${screen==='inbox'?inbox():screen==='queue'?issueQueue():issue()}</div></div>`;
}
function focusReview(){document.querySelector('#review-title')?.focus({preventScroll:true});if(innerWidth<800)document.querySelector('.review-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}
function setView(next){view=next;history.replaceState(null,'',`#${view}`);render();}
document.querySelectorAll('[data-view]').forEach(item=>item.addEventListener('click',()=>setView(item.dataset.view)));
document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();setView('prototype');screen='inbox';render();});
root.addEventListener('input',event=>{if(event.target.id==='correction')draft=event.target.value;});
root.addEventListener('change',event=>{if(event.target.dataset.check){dispatch({type:'check',name:event.target.dataset.check,checked:event.target.checked});document.querySelector(`[data-check="${event.target.dataset.check}"]`)?.focus({preventScroll:true});}});
root.addEventListener('submit',event=>{if(event.target.id==='search-form'){event.preventDefault();searchQuery=document.querySelector('#sample-search').value.trim();render();return;}if(event.target.id!=='correction-form')return;event.preventDefault();if(draft.trim().length<8){error='Please write at least 8 characters so the correction has enough context.';render();document.querySelector('#correction')?.focus();return;}const text=draft;draft='';error='';reviewTab='understanding';dispatch({type:'correct',text,kind});notify('Correction recorded. Work is paused for re-evaluation.');focusReview();});
root.addEventListener('click',event=>{
  const target=event.target.closest('button');if(!target)return;
  if(target.dataset.tab){reviewTab=target.dataset.tab;render();document.querySelector(`[data-tab="${reviewTab}"]`)?.focus({preventScroll:true});return;}
  if(target.dataset.kind){kind=target.dataset.kind;draft=exampleCorrections[kind];error='';render();document.querySelector('#correction')?.focus({preventScroll:true});return;}
  if(target.dataset.category){inboxCategory=target.dataset.category;render();return;}
  const action=target.dataset.action;if(!action)return;
  if(['filter','sort','new-issue','platform'].includes(action)){const feedback=document.querySelector('#toolbar-feedback');feedback.hidden=false;feedback.textContent=({filter:'Sample filters: one desktop design issue. Use the status tabs or Inbox lists to switch views.',sort:'Sorted by top votes. This prototype contains one sample issue.', 'new-issue':'This prototype focuses on reviewing an existing issue. Creating new issues is outside its scope.',platform:'Platform: All. The sample issue is on Desktop.'})[action];return;}
  if(action==='search'){searchOpen=!searchOpen;render();if(searchOpen)document.querySelector('#sample-search')?.focus();return;}
  if(action==='clear-filters'){searchQuery='';inboxCategory='input';render();return;}
  if(action==='queue'){screen='queue';listStatus=target.dataset.status;reviewOpen=false;render();return;}
  if(action==='review'){screen='issue';reviewOpen=true;reviewTab='understanding';render();focusReview();}
  else if(action==='issue'){screen='issue';reviewOpen=false;render();}
  else if(action==='inbox'){screen='inbox';reviewOpen=false;render();}
  else if(action==='close-review'){reviewOpen=false;render();root.querySelector('[data-action="review"]')?.focus({preventScroll:true});}
  else if(action==='try'){screen='inbox';reviewOpen=false;setView('prototype');root.scrollIntoView({behavior:'smooth',block:'start'});}
  else if(action==='reset')resetDemo();
  else if(['recheck','agree','approve','complete','reopen','pause'].includes(action)){if(action==='approve'){screen='issue';reviewOpen=true;}reviewTab='understanding';dispatch({type:action});notify(phaseLabels[state.phase]+'.');focusReview();}
});
root.addEventListener('keydown',event=>{if(event.target.getAttribute('role')!=='tab')return;if(['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();const tabs=['understanding','evidence','history'];const next=event.key==='Home'?0:event.key==='End'?2:(tabs.indexOf(reviewTab)+(event.key==='ArrowRight'?1:2))%3;reviewTab=tabs[next];render();document.querySelector(`[data-tab="${reviewTab}"]`)?.focus({preventScroll:true});}});
addEventListener('hashchange',()=>{view=['current','reasoning'].includes(location.hash.slice(1))?location.hash.slice(1):'prototype';render();});
const theme=document.querySelector('#theme');
try{document.documentElement.classList.toggle('light',localStorage.getItem('ziki-understanding-theme')==='light');}catch{}
function syncTheme(){const light=document.documentElement.classList.contains('light');theme.textContent=light?'☾':'☼';theme.setAttribute('aria-label',light?'Switch to dark mode':'Switch to light mode');document.querySelector('meta[name="theme-color"]').content=light?'#f6f8fc':'#0b152b';}
theme.addEventListener('click',()=>{document.documentElement.classList.toggle('light');syncTheme();try{localStorage.setItem('ziki-understanding-theme',document.documentElement.classList.contains('light')?'light':'dark');}catch{}});
function resetDemo(){state=initialState();draft='';error='';kind='scope';inboxCategory='input';searchQuery='';searchOpen=false;screen='inbox';reviewOpen=false;reviewTab='understanding';save();render();notify('Demo reset. No live work was changed.');}
document.querySelector('#footer-reset').addEventListener('click',resetDemo);
document.querySelector('#footer-theme').addEventListener('click',()=>theme.click());
syncTheme();render();
